<script>
	let text = $state('');

	const wordCount = $derived.by(() => {
		const trimmed = text.trim();
		if (trimmed === '') {
			return 0;
		}
		return trimmed.split(/\s+/).length;
	});

	const charCount = $derived.by(() => text.length);

	const isLong = $derived.by(() => {
		return wordCount > 15;
	});
</script>

<div>
	<input
		data-testid="text-input"
		type="text"
		bind:value={text}
		placeholder="Type something here..."
	/>
	<button data-testid="clear-button" onclick={() => (text = '')}>Clear</button>
	<div>
		<p data-testid="word-count">Words: {wordCount}</p>
		<p data-testid="char-count">Characters: {charCount}</p>
		<p data-testid="length-indicator">Status: {isLong ? 'Long text' : 'Short text'}</p>
	</div>
</div>
