```svelte
<script>
	let text = $state("Hello world");

	$inspect(text);

	const inspector = $inspect({ text }).with((value) => {
		console.log("[custom] text updated to:", value.text);
	});

	$effect(() => {
		$inspect.trace();
		console.log("[effect] reran because text changed to:", inspector.current.text);
	});

	let charCount = $state(text.length);

	$effect(() => {
		charCount = text.length;
	});
</script>

<div>
	<input data-testid="text-input" type="text" bind:value={text} />
	<p data-testid="text-value">Current text: "{text}"</p>
	<p data-testid="char-count">Character count: {charCount}</p>
</div>
